// Textos-base oficiais de provas e cadernos ETE PE usados por múltiplas questões
const TXT_DESIGUALDADE =
  'Se alguém te pedisse para trabalhar de graça até o final do ano, você aceitaria? Provavelmente não.\nMas é o que de certa forma ocorre com as mulheres, na visão de um grupo de ativistas por igualdade de salários, que, levando em conta a diferença salarial entre homens e mulheres na Grã-Bretanha (14,2%), calculou que as britânicas “pararam de receber” neste ano na segunda-feira passada, dia 9.\nEm um mundo com salários iguais para o mesmo trabalho, homens e mulheres trabalhariam 365 dias por ano recebendo o mesmo. No Brasil, devido à desigualdade de salários entre homens e mulheres, elas já estão trabalhando “de graça” desde o dia 19 de outubro de 2015.\nO cálculo foi feito com base em estatísticas do IBGE pela especialista em economia de gênero Regina Madalozzo, do Insper, a pedido da BBC Brasil.';

const TXT_ATENCAO =
  'A cultura digital disseminou a crença de que as novas gerações desenvolveram a habilidade cerebral de realizar múltiplas tarefas complexas simultaneamente. Ver um vídeo, responder a mensagens instantâneas e ler um artigo acadêmico ao mesmo tempo são ações frequentemente celebradas como prova de agilidade mental. No entanto, a neurociência contemporânea adverte que o cérebro humano não processa fluxos cognitivos densos em paralelo; o que ele faz, na verdade, é alternar o foco de forma frenética entre uma atividade e outra.\nEsse mecanismo de chaveamento contínuo tem um custo biológico elevado. Cada transição exige gasto de energia metabólica e fragmenta a capacidade de retenção de memória profunda. Por isso, estudantes que mantêm telas abertas durante os períodos de estudo levam mais tempo para consolidar conteúdos e cometem mais deslizes em avaliações analíticas. Eles têm a sensação subjetiva de produtividade elevada, mas apresentam desempenho acadêmico significativamente inferior.\nPara contornar esse prejuízo cognitivo, especialistas em educação recomendam o retorno deliberado ao foco unitemático. Estabelecer blocos de trabalho sem interrupções sonoras ou notificações visuais constitui um desafio urgente em tempos de estímulos permanentes.';

const TXT_RELOGIO_BOLSO =
  'O velho relógio de bolso repousava na gaveta como um fóssil de metal prateado. Não funcionava havia décadas, desde o dia em que o avô Antônio adoeceu e a casa pareceu perder o próprio compasso. Certo domingo de chuva, resolvi levá-lo a um relojoeiro tradicional da cidade baixa, daqueles artesãos raros que ainda usam lupa presa à órbita do olho e pinças milimétricas.\nO homem abriu a tampa traseira com paciência cirúrgica, limpou as engrenagens oxidadas e recolocou o pêndulo no eixo. À medida que ajustava cada pequena mola, o profissional explicava que máquinas mecânicas não suportam a inércia; elas precisam de movimento para que os óleos internos não endureçam. Quando a engrenagem principal deu o primeiro estalo rítmico, pareceu-me que o próprio tempo da infância voltava a pulsar.\nAquele tique-taque ritmado não era apenas um registro de segundos, mas a recuperação de uma voz que o esquecimento tentara apagar. Paguei o conserto com gosto. Voltei para casa sentindo o peito aquecido por uma certeza singular: certas ausências não se curam com o passar dos dias, mas se abrandam quando encontramos uma forma sensível de mantê-las presentes.';

const TXT_GARCA =
  'À beira de uma lagoa cristalina, pousava diariamente uma jovem garça de plumagem imaculada. Passava as manhãs entretida em contemplar sua própria figura refletida no remanso do riacho. Fascinada pelas linhas elegantes de seu pescoço e pela brancura de suas asas, pouco se importava com as correntes do rio ou com os avisos das outras aves, que a alertavam sobre a chegada iminente da seca.\nCerto dia, um pequeno peixe prateado subiu à superfície d’água, a escassos centímetros de suas garras. Seria a refeição perfeita para saciar a fraqueza que já começava a prostrá-la. Contudo, ao abaixar o bico para capturar a presa, a garça viu sua imagem se desmanchar em ondas circulares. Assustada com a perda momentânea daquele belo reflexo, recuou a cabeça, preferindo manter a postura altiva e imóvel. O peixe, esperto e arisco, aproveitou o vacilo e mergulhou nas profundezas lodosas.\nAo entardecer, quando a fome já lhe apertava as entranhas com rigor, o lago secou sob o sol inclemente, restando apenas poeira e pedregulhos cinzentos. Diante do leito vazio, a ave compreendeu, tarde demais, que a vaidade vazia não alimenta o corpo e que admirar a própria sombra custa caro quando a realidade exige ação imediata.';

const TXT_SENTINELAS =
  'Quando pensamos na polinização das lavouras e na reprodução das florestas, a imagem de abelhas zumbindo sob a luz radiante da manhã costuma ocupar de imediato o imaginário popular. No entanto, um contingente vital e muitas vezes negligenciado de trabalhadores ecológicos atua enquanto o mundo dorme: os polinizadores noturnos. Entre eles, destacam-se espécies de mariposas e morcegos frugívoros e nectarívoros, responsáveis pela fecundação de centenas de plantas com flores de abertura exclusivamente crepuscular.\nAlém da polinização indispensável, muitos desses animais prestam um serviço inestimável à produção agrícola atuando no controle biológico. Morcegos insetívoros, por exemplo, devoram toneladas de besouros, lagartas e mosquitos nocivos a cada noite. Esse comportamento predatório reduz a necessidade do uso massivo de agrotóxicos sintéticos, barateando a produção de alimentos e protegendo as fontes de água potável contra a contaminação química.\nInfelizmente, a expansão desenfreada da iluminação artificial nas zonas rurais e urbanas vem desorientando gravemente esses animais, impedindo que cumpram seus percursos migratórios e alimentares. Conhecer a importância dos polinizadores noturnos é o primeiro passo para planejar cidades mais equilibradas, adotando luminárias direcionadas e corredores ecológicos que garantam a sobrevivência desses guardiões da biodiversidade.';

const TXT_PEDRAS_PERGAMINHOS =
  'Antes de as palavras habitarem os suportes flexíveis e leves que conhecemos, registrar o pensamento era um esforço físico hercúleo. Povos da Mesopotâmia cravavam símbolos cuneiformes em placas de argila fresca, que depois secavam ao calor do fogo. Embora tais tábuas fossem duradouras — muitas atravessaram milênios intactas —, transportá-las constituía uma limitação logística intransponível para expedições comerciais e correspondências diplomáticas.\nCom o advento do papiro às margens do Nilo e, posteriormente, do pergaminho de pele animal no Mediterrâneo, a circulação dos textos ganhou dinamismo. O pergaminho, o qual possuía grande resistência mecânica e aceitava a raspagem para reescrita, tornou-se o suporte preferencial durante séculos nos mosteiros medievais. Não obstante, sua confecção exigia rebanhos inteiros de ovelhas ou bezerros para a composição de um único exemplar bíblico, o que mantinha os livros como artigos de luxo exclusivo da nobreza e do clero.\nApenas no século XV, quando a técnica chinesa de fabricação do papel vegetal combinou-se aos tipos móveis de chumbo criados por Johannes Gutenberg, a palavra escrita pôde enfim romper os muros dos castelos. O barateamento dos materiais permitiu que o conhecimento deixasse de ser privilégio sagrado e se convertesse no motor definitivo da ciência moderna.';

const TXT_CIDADE_ACORDA =
  'Às cinco da manhã, a grande avenida não pertence aos automóveis velozes nem aos executivos apressados. Pertence aos varredores de calçada, às padeiras que enfarinham as primeiras fornadas e aos entregadores de jornal que cortam o asfalto úmido de sereno. Há uma calma quase musical nesse prelúdio da rotina: o ruído ritmado das vassouras de piaçava no chão de pedra, o apito distante da composição de trens e o cheiro doce de café passado que escapa das portas entreabertas.\nA cidade parece respirar fundo antes da invasão do barulho. Os trabalhadores da madrugada trocam cumprimentos breves, cúmplices silenciosos de uma jornada invisível. No entanto, basta o relógio tocar as seis horas e trinta minutos para que o feitiço se desfaça. Motores rugem na esquina, pedestres aceleram o passo com os olhos fixos na tela do celular e a poesia da alvorada é engolida pelo ritmo frenético do comércio. Quem assiste a essa transição diária percebe que existem duas metrópoles sobre o mesmo solo: a que desperta com a alma serena e a que corre sem saber exatamente para onde vai.';

const TXT_CIDADES_PESSOAS =
  'Durante todo o século XX, o planejamento urbano priorizou as máquinas em detrimento dos indivíduos. Abertura de vias expressas, viadutos faraônicos e alargamento de pistas asfaltadas foram executados à custa da supressão de árvores e do encolhimento das calçadas. O resultado dessa escolha histórica salta aos olhos em qualquer capital: engarrafamentos diários intermináveis, poluição atmosférica severa e um ambiente hostil para quem necessita se deslocar a pé.\nA reversão desse modelo desumanizado requer uma mudança estrutural de perspectiva. Uma cidade verdadeiramente moderna é aquela em que o pedestre, o ciclista e o transporte coletivo recebem a prioridade absoluta nos investimentos públicos. Alargar calçadas, implantar ciclovias seguras e arborizar os caminhos cotidianos não são caprichos estéticos; representam medidas de saúde pública e justiça social, já que promovem a inclusão dos cidadãos de menor renda e diminuem o sedentarismo.\nRecuperar as calçadas é devolver a cidade ao seu legítimo habitante. Uma rua viva, com comércio de bairro e pessoas circulando livremente no passeio público, gera segurança coletiva e fomenta a cidadania ativa. O progresso de um centro urbano não se mede pela quantidade de automóveis particulares que cruzam seus túneis, mas pela dignidade e pelo conforto com que seus habitantes caminham por suas ruas.';

const TXT_REDE_FLORESTA =
  'Pesquisas recentes na área da ecologia vegetal revelaram que as árvores não vivem isoladas como simples competidoras individuais por luz e solo. Embaixo da terra, existe uma intrincada malha de filamentos de fungos, conhecida como micorriza, que conecta as raízes de diferentes árvores, formando uma verdadeira rede subterrânea de cooperação. Por meio dessa teia, árvores maduras transferem nutrientes essenciais para mudas jovens que crescem à sua sombra e que, de outro modo, não sobreviveriam à escassez de radiação solar.\nContudo, a função do sistema não se resume à nutrição compartilhada. Quando uma árvore é atacada por pragas ou insetos predadores, ela emite sinais bioquímicos através dessa malha fungosa, alertando as plantas vizinhas sobre a ameaça. As árvores receptoras, ao receberem o comunicado químico, ativam prematuramente seus próprios mecanismos de defesa, produzindo substâncias tóxicas ou repelentes antes mesmo de sofrerem o ataque.\nCientistas chamam essa dinâmica de cooperação interespecífica, uma vez que a floresta passa a operar como um organismo coletivo e integrado. Preservar uma área florestal, portanto, exige mais do que manter troncos em pé; demanda a integridade biológica do solo, sem a qual os vínculos vitais que sustentam todo o ecossistema se rompem silenciosamente.';

const TXT_CAATINGA =
  'Durante décadas, a vegetação nativa que protegia os mananciais do Agreste pernambucano foi suprimida para dar lugar a pastagens efêmeras e lavouras improvisadas. O resultado não tardou a se manifestar: nascentes outrora perenes tornaram-se intermitentes, e o solo, despido de sua cobertura protetora, começou a sofrer severo processo de erosão.\nRecentemente, iniciativas de reflorestamento comunitário vêm revertendo esse quadro desolador. Agricultores familiares reuniram-se para plantar mudas nativas, como o juazeiro, a catingueira e o mandacaru. Ao restabelecer a mata ciliar, a comunidade não apenas preservou as espécies vegetais, mas também garantiu a recarga dos lençóis freáticos. O riacho que banha a vila voltou a correr límpido após anos de seca e abandono.\nEssa restauração ecológica despertou novos hábitos entre os moradores. A água farta, que antes parecia um privilégio inatingível, transformou-se no esteio da subsistência coletiva. A convivência harmoniosa com o bioma provou que o desenvolvimento sustentável não é uma quimera distante, mas uma prática viável que brota do trabalho conjunto e do respeito aos ciclos naturais.';

const TXT_RELOGIO_TORRE =
  'Na pacata cidade de Serrinha, as horas não pertenciam aos homens, mas à engrenagem de ferro do relógio da torre matriz. Quando o carrilhão soava, os passos nas calçadas aceleravam, as portas de madeira se cerravam e os operários convergiam para o portão da velha tecelagem. O sino ditava o compasso dos risos, dos lutos e das preces.\nSeu Sebastião, o zombeteiro relojoeiro da praça, costumava dizer que o tempo ali era um animal domesticado. Ninguém ousava contestar a autoridade daquele gigante de bronze. Certo dia, contudo, um raio fulminou o campanário, partindo o pêndulo principal. O silêncio que se instalou foi ensurdecedor.\nSem as batidas pontuais, a rotina esfacelou-se. Moradores olhavam para o céu desorientados, incapazes de precisar se era tempo de almoçar ou de recolher as ferramentas. Foi então que perceberam: haviam delegado a própria vida a um maquinismo cego, esquecendo-se de que a verdadeira medida da existência mora na pulsação do próprio peito.';

const TXT_CIDADE_ADORMECIDA =
  'A noite despeja seu manto de veludo sobre os telhados úmidos.\nO asfalto bebe a chuva fria com avidez insaciável,\nenquanto os postes cochilam em fileiras amarelas.\nNa esquina deserta, o vento uiva segredos antigos,\nferindo o silêncio com adagas de gelo.\nChoram as vidraças velhas lágrimas de vapor e poeira;\no tempo corre veloz, mas a tristeza anda a passos de tartaruga.\nA cidade é um peito de pedra que pulsa em agonia lenta,\nesperando o sol que há de nascer para queimar todas as dores.';

