  'O Porto Digital, um dos maiores polos de tecnologia do Brasil, tem hoje 3.200 vagas abertas e não preenchidas para atuação em áreas de Tecnologia da Informação e Comunicação. A informação foi divulgada pelo professor e cientista Silvio Meira, em entrevista ao programa Super Manhã, da Rádio Jornal.\n“A gente tinha 1.500 vagas em aberto no Porto Digital, passou para duas mil vagas, e agora estamos com três mil vagas em aberto...”, disse.\nHoje, 12 mil pessoas trabalham no parque tecnológico, onde 340 empresas estão embarcadas.';

